const WA_HIGHER_BETTER=new Set(['HJ','PV','LJ','TJ','SP','DT','HT','JT','Hept. sh','Dec.','Pent. sh','Hept.']);
const WA_INDOOR_BASE=new Set(['50m','55m','60m','50mH','55mH','60mH','HJ','PV','LJ','TJ','SP']);
const WA_LABELS={'HJ':'High Jump','PV':'Pole Vault','LJ':'Long Jump','TJ':'Triple Jump','SP':'Shot Put','DT':'Discus Throw','HT':'Hammer Throw','JT':'Javelin Throw','HM':'Half Marathon','HMW':'Half Marathon Walk','MarW':'Marathon Walk','Dec.':'Decathlon','Hept.':'Heptathlon','Hept. sh':'Heptathlon','Pent. sh':'Pentathlon','4x400mix':'Mixed 4×400m','4x400mix sh':'Mixed 4×400m','2 Miles':'2 Miles','2 Miles sh':'2 Miles','Mile road':'Mile Road'};
function waNice(k){let x=WA_LABELS[k]||k; x=x.replace(/ sh$/,'').replace(/ SC$/,' Steeplechase').replace(/ W road$/,' Walk').replace(/W$/,' Walk').replace(/ road$/,' Road'); return x;}
function waIsIndoor(k){return k.endsWith(' sh')||WA_INDOOR_BASE.has(k)}
function waNumMark(s){s=String(s).trim().replace(',','.');if(!s)return NaN;if(s.includes(':')){let p=s.split(':').map(Number);if(p.some(Number.isNaN))return NaN;return p.reduce((a,v)=>a*60+v,0)}return Number(s)}
function waScore(sex,event,raw){
  const v=waNumMark(raw), arr=DATA?.[sex]?.[event];
  if(!Number.isFinite(v)||!arr)return {score:null,matched:null,status:'invalid'};
  const high=WA_HIGHER_BETTER.has(event);
  let found=null;
  for(const [pts,m] of arr){const mv=waNumMark(m);if(high?v>=mv:v<=mv){found=[pts,m];break}}
  if(!found)return {score:0,matched:null,status:'below'};
  return {score:found[0],matched:found[1],status:'ok'};
}
function waEvents(sex,environment){
  return Object.keys(DATA?.[sex]||{}).filter(k=>environment==='Indoor'?waIsIndoor(k):!k.endsWith(' sh')).sort((a,b)=>waNice(a).localeCompare(waNice(b)));
}
